class Solution:
    def minSubsequence(self, nums: List[int]) -> List[int]:
        total = sum(nums)
        nums.sort(reverse=True)
        res = []
        cur = 0
        for x in nums:
            cur += x
            res.append(x)
            if cur * 2 > total:
                break
        return res

