class Solution {
public:
    vector<int> minSubsequence(vector<int>& nums) {
        long long total = accumulate(nums.begin(), nums.end(), 0LL);
        sort(nums.rbegin(), nums.rend());
        vector<int> res;
        long long cur = 0;
        for (int x : nums) {
            cur += x;
            res.push_back(x);
            if (cur * 2 > total) break;
        }
        return res;
    }
};

