class Solution:
    def minSubsequence(self, nums: List[int]) -> List[int]:
        total = sum(nums)
        cnt = [0] * 101
        for x in nums:
            cnt[x] += 1
        res = []
        cur = 0
        for v in range(100, 0, -1):
            for _ in range(cnt[v]):
                cur += v
                res.append(v)
                if cur * 2 > total:
                    return res
        return res

