        for (int x : nums) { cnt[x]++; total += x; }
        vector<int> res;
        int cur = 0;
        for (int v = 100; v >= 1; v--) {
            while (cnt[v]--) {
                cur += v;
                res.push_back(v);
                if (cur * 2 > total) return res;
            }
        }
        return res;
    }
};

